CREATE TABLE evaluation_inbox (event_id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, event_version INTEGER NOT NULL, content_digest CHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, processed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_evaluation_inbox_tenant_status ON evaluation_inbox (tenant_id, status);
CREATE TABLE evaluation_candidate (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, source_event_id UUID NOT NULL, anonymized_body JSONB, body_digest CHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, anonymization_rule_version VARCHAR(64) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, UNIQUE (tenant_id, source_event_id));
CREATE INDEX idx_evaluation_candidate_retention ON evaluation_candidate (tenant_id, status, expires_at);
CREATE TABLE evaluation_candidate_review (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, candidate_id UUID NOT NULL REFERENCES evaluation_candidate(id), reviewer_id VARCHAR(128) NOT NULL, action VARCHAR(32) NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evaluation_dataset (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, name VARCHAR(256) NOT NULL, state VARCHAR(32) NOT NULL, UNIQUE (tenant_id, name));
CREATE TABLE evaluation_dataset_version (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, dataset_id UUID NOT NULL REFERENCES evaluation_dataset(id), version_number INTEGER NOT NULL, content_digest CHAR(64) NOT NULL, visibility VARCHAR(32) NOT NULL, published_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (tenant_id, dataset_id, version_number));
CREATE TABLE evaluation_sample_snapshot (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, dataset_version_id UUID NOT NULL REFERENCES evaluation_dataset_version(id), sample_json JSONB NOT NULL, UNIQUE (tenant_id, dataset_version_id, id));
CREATE TABLE evaluation_run (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, dataset_version_id UUID NOT NULL, manifest_digest CHAR(64) NOT NULL, mode VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE (tenant_id, id));
CREATE TABLE evaluation_result (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, run_id UUID NOT NULL REFERENCES evaluation_run(id), sample_id UUID NOT NULL, evidence_json JSONB NOT NULL, UNIQUE (tenant_id, run_id, sample_id));
CREATE TABLE evaluation_gate_policy (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, version VARCHAR(64) NOT NULL, policy_json JSONB NOT NULL, UNIQUE (tenant_id, version));
CREATE TABLE evaluation_gate_decision (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, artifact_type VARCHAR(64) NOT NULL, artifact_version_id UUID NOT NULL, manifest_digest CHAR(64) NOT NULL, policy_version VARCHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, signature TEXT NOT NULL, key_id VARCHAR(128) NOT NULL, UNIQUE (tenant_id, artifact_type, artifact_version_id, manifest_digest, policy_version));
CREATE TABLE evaluation_gate_revocation (id UUID PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, decision_id UUID NOT NULL, reason TEXT NOT NULL, revoked_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (tenant_id, decision_id));
